import sys

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        N = int(sys.stdin.readline())
        A = list(map(int, sys.stdin.readline().split()))
        possible = True
        for num in A:
            if num < 2:
                possible = False
                break
        if not possible and N > 1:
            print(-1)
        else:
            total = sum(A)
            res = max(2 * N, total - (N - 2))
            print(res)

solve()
